class Solution {
public:
    bool scoreBalance(string s) {
        int total = 0;
        for (char c : s) total += c - 'a' + 1;
        int left = 0;
        for (int i = 0; i + 1 < (int)s.size(); ++i) {
            left += s[i] - 'a' + 1;
            if (2 * left == total) return true;
        }
        return false;
    }
};
